"""Static PostgreSQL seed migration for protected RBAC system roles.

The permission sets below are an intentional snapshot of the defaults at
migration creation time. Future permission changes require a new migration.
"""

from ..migration_runner import Migration


RBAC_SEED_PERMISSIONS = {
    'administrator': frozenset(('alerts.manage', 'alerts.view', 'backups.manage', 'clients.manage', 'clients.view', 'infrastructure.manage', 'jobs.manage', 'packages.search', 'software.view', 'system.update', 'updates.view', 'users.manage')),
    'operator': frozenset(('clients.view', 'jobs.manage', 'packages.search', 'software.view', 'updates.view')),
    'viewer': frozenset(('clients.view', 'software.view')),
}

RBAC_SEED_MIGRATION = Migration(
    version="004-rbac-system-roles",
    description="Seed protected system roles and default permissions",
    statements=(
        "INSERT INTO roles (\n            role_key,\n            name,\n            description,\n            is_system,\n            is_migration,\n            created_at,\n            updated_at\n        )\n        VALUES (\n            'system-administrator',\n            'Administrator',\n            'Geschützte LUMS-Systemrolle',\n            TRUE,\n            FALSE,\n            CURRENT_TIMESTAMP::text,\n            CURRENT_TIMESTAMP::text\n        )\n        ON CONFLICT (role_key) DO NOTHING",
        "DO $lums$\n        BEGIN\n            IF NOT EXISTS (\n                SELECT 1\n                FROM roles\n                WHERE role_key = 'system-administrator'\n                  AND name = 'Administrator'\n                  AND is_system IS TRUE\n                  AND is_migration IS FALSE\n            ) THEN\n                RAISE EXCEPTION\n                    'RBAC system role conflict: system-administrator';\n            END IF;\n        END;\n        $lums$",
        "INSERT INTO roles (\n            role_key,\n            name,\n            description,\n            is_system,\n            is_migration,\n            created_at,\n            updated_at\n        )\n        VALUES (\n            'system-operator',\n            'Operator',\n            'Geschützte LUMS-Systemrolle',\n            TRUE,\n            FALSE,\n            CURRENT_TIMESTAMP::text,\n            CURRENT_TIMESTAMP::text\n        )\n        ON CONFLICT (role_key) DO NOTHING",
        "DO $lums$\n        BEGIN\n            IF NOT EXISTS (\n                SELECT 1\n                FROM roles\n                WHERE role_key = 'system-operator'\n                  AND name = 'Operator'\n                  AND is_system IS TRUE\n                  AND is_migration IS FALSE\n            ) THEN\n                RAISE EXCEPTION\n                    'RBAC system role conflict: system-operator';\n            END IF;\n        END;\n        $lums$",
        "INSERT INTO roles (\n            role_key,\n            name,\n            description,\n            is_system,\n            is_migration,\n            created_at,\n            updated_at\n        )\n        VALUES (\n            'system-viewer',\n            'Viewer',\n            'Geschützte LUMS-Systemrolle',\n            TRUE,\n            FALSE,\n            CURRENT_TIMESTAMP::text,\n            CURRENT_TIMESTAMP::text\n        )\n        ON CONFLICT (role_key) DO NOTHING",
        "DO $lums$\n        BEGIN\n            IF NOT EXISTS (\n                SELECT 1\n                FROM roles\n                WHERE role_key = 'system-viewer'\n                  AND name = 'Viewer'\n                  AND is_system IS TRUE\n                  AND is_migration IS FALSE\n            ) THEN\n                RAISE EXCEPTION\n                    'RBAC system role conflict: system-viewer';\n            END IF;\n        END;\n        $lums$",
        "INSERT INTO role_permissions (role_id, permission)\n        SELECT roles.id, expected.permission\n        FROM roles\n        CROSS JOIN (\n            VALUES\n                ('alerts.manage'),\n                ('alerts.view'),\n                ('backups.manage'),\n                ('clients.manage'),\n                ('clients.view'),\n                ('infrastructure.manage'),\n                ('jobs.manage'),\n                ('packages.search'),\n                ('software.view'),\n                ('system.update'),\n                ('updates.view'),\n                ('users.manage')\n        ) AS expected(permission)\n        WHERE roles.role_key = 'system-administrator'\n        ON CONFLICT (role_id, permission) DO NOTHING",
        "DO $lums$\n        BEGIN\n            IF EXISTS (\n                SELECT permission\n                FROM role_permissions\n                WHERE role_id = (\n                    SELECT id\n                    FROM roles\n                    WHERE role_key = 'system-administrator'\n                )\n                EXCEPT\n                SELECT expected.permission\n                FROM (\n                    VALUES\n                        ('alerts.manage'),\n                ('alerts.view'),\n                ('backups.manage'),\n                ('clients.manage'),\n                ('clients.view'),\n                ('infrastructure.manage'),\n                ('jobs.manage'),\n                ('packages.search'),\n                ('software.view'),\n                ('system.update'),\n                ('updates.view'),\n                ('users.manage')\n                ) AS expected(permission)\n            )\n            OR EXISTS (\n                SELECT expected.permission\n                FROM (\n                    VALUES\n                        ('alerts.manage'),\n                ('alerts.view'),\n                ('backups.manage'),\n                ('clients.manage'),\n                ('clients.view'),\n                ('infrastructure.manage'),\n                ('jobs.manage'),\n                ('packages.search'),\n                ('software.view'),\n                ('system.update'),\n                ('updates.view'),\n                ('users.manage')\n                ) AS expected(permission)\n                EXCEPT\n                SELECT permission\n                FROM role_permissions\n                WHERE role_id = (\n                    SELECT id\n                    FROM roles\n                    WHERE role_key = 'system-administrator'\n                )\n            ) THEN\n                RAISE EXCEPTION\n                    'RBAC permission mismatch for role: system-administrator';\n            END IF;\n        END;\n        $lums$",
        "INSERT INTO role_permissions (role_id, permission)\n        SELECT roles.id, expected.permission\n        FROM roles\n        CROSS JOIN (\n            VALUES\n                ('clients.view'),\n                ('jobs.manage'),\n                ('packages.search'),\n                ('software.view'),\n                ('updates.view')\n        ) AS expected(permission)\n        WHERE roles.role_key = 'system-operator'\n        ON CONFLICT (role_id, permission) DO NOTHING",
        "DO $lums$\n        BEGIN\n            IF EXISTS (\n                SELECT permission\n                FROM role_permissions\n                WHERE role_id = (\n                    SELECT id\n                    FROM roles\n                    WHERE role_key = 'system-operator'\n                )\n                EXCEPT\n                SELECT expected.permission\n                FROM (\n                    VALUES\n                        ('clients.view'),\n                ('jobs.manage'),\n                ('packages.search'),\n                ('software.view'),\n                ('updates.view')\n                ) AS expected(permission)\n            )\n            OR EXISTS (\n                SELECT expected.permission\n                FROM (\n                    VALUES\n                        ('clients.view'),\n                ('jobs.manage'),\n                ('packages.search'),\n                ('software.view'),\n                ('updates.view')\n                ) AS expected(permission)\n                EXCEPT\n                SELECT permission\n                FROM role_permissions\n                WHERE role_id = (\n                    SELECT id\n                    FROM roles\n                    WHERE role_key = 'system-operator'\n                )\n            ) THEN\n                RAISE EXCEPTION\n                    'RBAC permission mismatch for role: system-operator';\n            END IF;\n        END;\n        $lums$",
        "INSERT INTO role_permissions (role_id, permission)\n        SELECT roles.id, expected.permission\n        FROM roles\n        CROSS JOIN (\n            VALUES\n                ('clients.view'),\n                ('software.view')\n        ) AS expected(permission)\n        WHERE roles.role_key = 'system-viewer'\n        ON CONFLICT (role_id, permission) DO NOTHING",
        "DO $lums$\n        BEGIN\n            IF EXISTS (\n                SELECT permission\n                FROM role_permissions\n                WHERE role_id = (\n                    SELECT id\n                    FROM roles\n                    WHERE role_key = 'system-viewer'\n                )\n                EXCEPT\n                SELECT expected.permission\n                FROM (\n                    VALUES\n                        ('clients.view'),\n                ('software.view')\n                ) AS expected(permission)\n            )\n            OR EXISTS (\n                SELECT expected.permission\n                FROM (\n                    VALUES\n                        ('clients.view'),\n                ('software.view')\n                ) AS expected(permission)\n                EXCEPT\n                SELECT permission\n                FROM role_permissions\n                WHERE role_id = (\n                    SELECT id\n                    FROM roles\n                    WHERE role_key = 'system-viewer'\n                )\n            ) THEN\n                RAISE EXCEPTION\n                    'RBAC permission mismatch for role: system-viewer';\n            END IF;\n        END;\n        $lums$",
    ),
)


__all__ = [
    "RBAC_SEED_MIGRATION",
    "RBAC_SEED_PERMISSIONS",
]
